<aside><div class="card"><div class="card-body p-4"><label class="form-label">Customer</label><select class="form-select mb-3" name="customer_id" required>@foreach($customers as $c)<option value="{{ $c->id }}">{{ $c->name }}</option>@endforeach</select><div class="row g-2 mb-3"><div class="col-6"><label class="form-label">Sale channel</label><select class="form-select" name="channel" id="channel"><option value="retail">Retail</option><option value="wholesale">Wholesale</option></select></div><div class="col-6"><label class="form-label">Sale type</label><select class="form-select" name="payment_type" id="sale-type"><option value="cash">Cash</option><option value="credit">Credit</option></select></div></div><div id="due-wrap" class="mb-3 d-none"><label class="form-label">Due date</label><input class="form-control" type="date" name="due_date"></div><hr><div class="d-flex justify-content-between"><span>Subtotal</span><strong id="subtotal">Rs. 0.00</strong></div><label class="form-label mt-3">Discount</label><input class="form-control" name="discount_amount" id="discount" type="number" value="0" min="0" step=".01"><div class="d-flex justify-content-between align-items-end mt-3"><span>Grand total</span><span class="pos-total" id="grand">Rs. 0.00</span></div><hr><label class="form-label">Payment method</label><select class="form-select mb-3" name="payment_method" id="method"><option value="cash">Cash</option><option value="credit_card">Credit Card</option><option value="debit_card">Debit Card</option><option value="qr">QR Payment</option><option value="cheque">Cheque</option><option value="bank_transfer">Bank Transfer</option><option value="mobile_wallet">Mobile Wallet</option><option value="online_payment">Online Payment</option></select><label class="form-label">Paid amount</label><input class="form-control mb-3" name="paid_amount" id="paid" type="number" min="0" step=".01" value="0"><div id="cheque" class="d-none"><input class="form-control mb-2" name="cheque_number" placeholder="Cheque number"><input class="form-control mb-2" name="cheque_bank" placeholder="Bank"><input class="form-control mb-3" type="date" name="cheque_date"></div><input class="form-control mb-3" name="payment_reference" placeholder="Payment reference (optional)"><button class="btn btn-success btn-lg w-100" id="post">Complete Sale</button></div></div></aside></div></form>
@push('scripts')<script>let idx=0,cart=new Map();const picker=document.querySelector('#product-picker'),body=document.querySelector('#cart'),channel=document.querySelector('#channel');function money(n){return'Rs. '+Number(n).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}function totals(){let s=0;body.querySelectorAll('tr[data-id]').forEach(r=>s+=Number(r.querySelector('.qty').value)*Number(r.querySelector('.price').value));let g=Math.max(0,s-Number(document.querySelector('#discount').value||0));document.querySelector('#subtotal').textContent=money(s);document.querySelector('#grand').textContent=money(g);if(document.querySelector('#sale-type').value==='cash')document.querySelector('#paid').value=g.toFixed(2)}function add(o){if(cart.has(o.value)){let q=cart.get(o.value).querySelector('.qty');q.value=Number(q.value)+1;totals();return}document.querySelector('#empty')?.remove();let r=document.createElement('tr');r.dataset.id=o.value;r.innerHTML=`<td class="ps-3"><strong>${o.dataset.name}</strong><div class="small text-muted">${o.dataset.code} · Available ${o.dataset.stock}</div><input type="hidden" name="items[${idx}][product_id]" value="${o.value}"></td><td><input class="form-control qty" name="items[${idx}][quantity]" type="number" min=".0001" max="${o.dataset.stock}" step=".0001" value="1"></td><td><input class="form-control price" name="items[${idx}][unit_price]" type="number" min="0" step=".01" value="${channel.value==='retail'?o.dataset.retail:o.dataset.wholesale}"></td><td class="line"></td><td><button class="btn btn-light remove" type="button">×</button></td>`;r.dataset.retail=o.dataset.retail;r.dataset.wholesale=o.dataset.wholesale;r.querySelectorAll('input').forEach(x=>x.oninput=totals);r.querySelector('.remove').onclick=()=>{cart.delete(o.value);r.remove();totals()};body.append(r);cart.set(o.value,r);idx++;totals()}picker.onchange=()=>{if(picker.value)add(picker.selectedOptions[0]);picker.value=''};channel.onchange=()=>{cart.forEach(r=>r.querySelector('.price').value=channel.value==='retail'?r.dataset.retail:r.dataset.wholesale);totals()};document.querySelector('#discount').oninput=totals;document.querySelector('#sale-type').onchange=e=>{document.querySelector('#due-wrap').classList.toggle('d-none',e.target.value!=='credit');totals()};document.querySelector('#method').onchange=e=>document.querySelector('#cheque').classList.toggle('d-none',e.target.value!=='cheque');</script>@endpush
